INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mayhem', 7066, '2011-03-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/esnxnwxkyukwzahlwnpj.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mayhem', 'Mayhem is a fast paced arcade racing and car destruction game. The inspiration for the game comes from two distinct types of events: Demolition Derby and Banger Racing. A demolition derby is more of an American pastime, primarily at state fairs and the like. Participants take an old beat down car, strip it of all the glass and other "dangerous" elements, spray paint the car and decorate it to their liking, then beat it to death at the main event. The last vehicle standing is the victor. A Banger Race is more practiced in the UK. Races take place on small courses with pits and hills, and drivers are encouraged to send their opponents off course. Courses can have hazards and obstacles, and the "figure 8" shaped course is a staple of the race. No matter whether it''s Banger races or demolition derbys, the fact is that everyone love to see the everyman take it to the mat and come out a victor, and that''s what Mayhem is all about.' FROM games WHERE igdb_id = 7066 ON CONFLICT (game_id, language_code) DO NOTHING;
