INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ironclads-anglo-russian-war-1866', 16156, '2011-06-21', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa3wd.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2bqe.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ironclads: Anglo Russian War 1866', 'Russia sought to seize control of Constantinople. The city controlled the Black Sea straits, an important economic and strategic point of the Black and Mediterranean Sea. This area was the cause of constant conflict with Britain, which was concerned about her Mediterranean interests. The Crimean War had weakened the position of Russia on the Black Sea, but, in the Baltic and North Sea, the Tsar built a new, modern fleet. In 1865, Poland rebelled against Russia. Britain supported the rebels and declared war on Russia. Two objectives of the Royal Navy were to destroy the Russian squadron in the North Sea and the establishment of a full blockade of the North.' FROM games WHERE igdb_id = 16156 ON CONFLICT (game_id, language_code) DO NOTHING;
