INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Steel Armor: Blaze of War', 'Keep your head cool for this brand new and sizzling hot game from the makers of renowned hardcore-strategy masterpieces like “Steel Fury” and “Achtung Panzer!” With highly versatile strategies and tactics it´s only fair to call their impressive new game “Steel Armor – Blaze of War” one of the most interesting and tactically advanced tank simulations of all time! Plan, command and fight in this exciting and extremely detailed blend of turn-based strategy, real time tactics and full-scaled tank simulation.' FROM games WHERE igdb_id = 9468 ON CONFLICT (game_id, language_code) DO NOTHING;
