INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gyakuten Puzzle Irekaeru Gyakuten', 'Gyakuten Puzzle Irekaeru Gyakuten is a competitive puzzle game for cellphones published by Capcom, based on the Ace Attorney series. The game is turn-based, where players compete to get points in order to push the gauge to their side (either "Guilty" or "Not Guilty"). Each player can gain and use items as well, such as a magatama, the Blue Badger, a bottle of luminol fluid, an attorney''s badge, a prosecutor''s badge, and a Steel Samurai trading card.' FROM games WHERE igdb_id = 256345 ON CONFLICT (game_id, language_code) DO NOTHING;
