INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Idolmaster: Gravure for You! - Vol. 1', 'The Idolmaster: Gravure For You! is a sub-series of games in the The Idolmaster series of games. In the games, the player can take pictures of idols wearing different outfits while posed. The original release of the game totaled 9 individual volumes released in bundles with episodes of The Idolmaster anime, containing the idols from 765 Production and guest idols from 876 Production. Another set of nine volumes in currently being released for characters from the Cinderella Girls anime.' FROM games WHERE igdb_id = 79980 ON CONFLICT (game_id, language_code) DO NOTHING;
