INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Candles', 'Candles is a short first-person horror game developed by TheUnbeholden. Set in a remote and shadowy home, players must navigate through unsettling interiors while managing limited interactions that shape their path forward. The game emphasizes atmosphere, using dynamic lighting, eerie sound design, and a compact, claustrophobic environment to build tension. Its minimalist mechanics focus attention on exploration and environmental storytelling, creating a suspenseful and immersive experience.' FROM games WHERE igdb_id = 341411 ON CONFLICT (game_id, language_code) DO NOTHING;
