INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tilt to Live', 'How do you play Tilt to Live? Just pick that bad boy up and tilt. Tilt for your life! Lure relentless red foes over to a handy nuke orb, then ram it and blow the bajeezes out of them. Think you can exterminate your enemies faster than they can multiply? Think again.' FROM games WHERE igdb_id = 51633 ON CONFLICT (game_id, language_code) DO NOTHING;
