INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dunamis 15', 'Dunamis 15 (デュナミス15 Dyunamisu 15?) is a suspense visual novel developed and published by 5pb. for the PlayStation 3 and Xbox 360. The game was released in Japan on September 15, 2011,[3] featuring five chapters and five main characters. A port for the PlayStation Portable was released on July 26, 2012.[4][5] The sequel title, Disorder 6, was released on August 22, 2013. This is the first title in Suspense-fiction Adventure series, a spinoff to famous Science Adventure series.' FROM games WHERE igdb_id = 6974 ON CONFLICT (game_id, language_code) DO NOTHING;
