INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Danball Senki', 'Danball Senki is a PSP game developed by Level 5 involving small plastic model robots known as LBXs (standing for "Little Battler eXperience") that fight on dioramas made out of cardboard, and the main character Ban Yamano setting out to battle against LBXs created by other characters. For international release, Level-5 adopted the English language title "Little Battlers eXperience."' FROM games WHERE igdb_id = 72572 ON CONFLICT (game_id, language_code) DO NOTHING;
