INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Endless Depths', 'Can you take down Mephistopheles? Endless Depths is a roguelike that challenges you to get past hordes of enemies from giant bats to skeletons to demons and overpowering giants. Down into the depths you will go, dodging traps and collecting weapons. And if you have enough luck and skill, you will face off with the lord of demons himself.' FROM games WHERE igdb_id = 354510 ON CONFLICT (game_id, language_code) DO NOTHING;
