INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hidden Expedition: The Uncharted Islands', 'Hidden Expedition: The Uncharted Islands is a hidden object game and the fifth entry into the Hidden Expedition series of "seek and find" games. The gameplay is similar to previous instalments, with the focus being on finding items scattered across a diverse collection of scenes. Some items are placed in the player''s inventory and need to be used in other locations to advance in the game. The game does feature some variations on the basic hidden object formula, with many hidden object scenes being two screens wide, and some items only being revealed by the manipulation of other items.' FROM games WHERE igdb_id = 64721 ON CONFLICT (game_id, language_code) DO NOTHING;
