INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('girp', 137545, '2011-03-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2o5b.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8y9a.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Girp', 'A spiritual successor of sorts to the developer''s earlier QWOP, this one takes the physical feats out of the realm of organized sport and instead puts the player in control of a man desperately clinging to a rocky oceanside cliff at sea level. Numerous handholds are available with which to pull himself up, helpfully labeled with keyboard letters, and if a handhold proves out of reach the player can activate a muscle-tensing big push, really striving to get close enough to the handhold to grab it. The player''s body is governed by ragdoll physics, meaning that sometimes some rocking or swinging motions are needed in order to get close enough to make use of a handhold. Additional challenge is provided by shore birds who have made their nests in the handholds, obscuring the relevant letter with their feathery little bodies, plus of course the gradually-rising tide.' FROM games WHERE igdb_id = 137545 ON CONFLICT (game_id, language_code) DO NOTHING;
