INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fifi and the Flowertots: Fifi''s Garden Party', 'In Fifi and the Flowertots: Fifi’s Garden Party, Fifi Forget-Me-Not has forgotten all about the party she’s planning! Help Fifi and Bumble explore the Flowertot Garden, solving 15 charming puzzle games to gather treats and decorations for the celebration. With three levels of difficulty and all your favourite Flowertot characters, this delightful game encourages memory, logic, and problem-solving skills in a colourful, kid-friendly world.' FROM games WHERE igdb_id = 336176 ON CONFLICT (game_id, language_code) DO NOTHING;
