INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bowser''s Last Stand', 'While Bowser is "training" in his castle by breaking bricks, he hears a loud "thud". Believing it to be Sumo Bros, he investigates, but is surprised to find that a group of Toads has broken into his castle. The Toads explain that while Bowser was "training", they had completely taken over the Koopa Kingdom.
