INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jerry Rice & Nitus'' Dog Football', 'Hall of Fame wide receiver, Jerry Rice and his dog Nitus hit the canine gridiron for some family-friendly, seven-on-seven action. Sports just aren’t for humans anymore! The dogs have turned pro as they compete alongside their owners for the coveted golden hydrant. 1 to 4 player season and exhibition modes, with 20 dog breeds, 14 human quarterbacks, 185 plays, and 12 Interactive Fields. It''s non-stop, "Lick Your Face" and "Wag Your Tail" action for the whole family.' FROM games WHERE igdb_id = 33586 ON CONFLICT (game_id, language_code) DO NOTHING;
