INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lovely x Cation', 'The protagonist lives alone in an apartment owned by his uncle and lives a carefree school life. One spring day, his uncle can’t stand seeing him confining himself in his room any more and tells him to go out and find love while he is still young. However, he doesn’t have any experience with girls nor does he have anyone that he’s interested in.' FROM games WHERE igdb_id = 135501 ON CONFLICT (game_id, language_code) DO NOTHING;
