INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dance Dance Revolution X3 VS 2ndMix', 'Dance Dance Revolution X3 is a music video game, and a part of the Dance Dance Revolution series. The arcade version of DDR X3 was revealed by Konami on June 2, 2011. The sequel to Dance Dance Revolution X2, X3 began public beta testing on June 8, 2011. Promotional information for the game revealed the full name for the game, called Dance Dance Revolution X3 VS 2ndMix due to the new "2ndMix" mode in the game. It was released in Japan on November 16, 2011 for dedicated cabinets and November 30, 2011 for upgrade kits, and December 16, 2011 in Asia.' FROM games WHERE igdb_id = 98239 ON CONFLICT (game_id, language_code) DO NOTHING;
