INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cyphers', 'Cyphers is a Korean, third-person MOBA style Action Game where two teams try to take down a series of barricades and towers to destroy the enemy''s main building and claim victory. The game has a strong emphasis on melee weapons and stylish attacks. Players may choose from a variety of 35 characters. It also has a unique progression system where the player''s level depends on the number of upgrades they have.' FROM games WHERE igdb_id = 62633 ON CONFLICT (game_id, language_code) DO NOTHING;
