INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Call of Thrones', 'Call of Thrones was a free-to-play action RPG that enables players to explore their own destiny while conquering territory and gaining power. The game''s 3D visuals and music offer players good graphics and smooth gameplay. In addition with detailed character customization and trade specialization systems, players direct the path of their heroes to win a war for their kingdom.' FROM games WHERE igdb_id = 143186 ON CONFLICT (game_id, language_code) DO NOTHING;
