INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Country Dance 2', 'Country Dance 2 is easy to jump in and play; just pick up the Wii RemoteEand replicate the onscreen dance moves to start earning points with hot country routines. Plus, Country Dance 2 now supports up to four players at once for a whole new level of multiplayer fun including the all new duet dancing option that features unique choreography for each player during the same song. Whether you’re cutting the rug on your own, line dancing side-by-side with your partner, or taking on friends and family in a dancing duel, Country Dance 2 will transform your living room into an energetic dance floor with mega hits from Amercia’s best-selling country artists.' FROM games WHERE igdb_id = 50927 ON CONFLICT (game_id, language_code) DO NOTHING;
