INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dark Parables: The Exiled Prince', 'Many centuries ago, a princess kissed a frog and transformed him into a handsome prince. Unlike the fable, they never ended happily ever after. It is rumored that the Frog Prince is still alive and now roams the deserted path in the Black Forest, capturing unsuspecting visitors. When the chancellor''s daughter goes missing, you are sent to investigate her disappearance. Journey through the deserted forest in Dark Parables – The Exiled Prince, an eerie Hidden Object Adventure game!' FROM games WHERE igdb_id = 27027 ON CONFLICT (game_id, language_code) DO NOTHING;
