INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cooking Mama 4: Kitchen Magic', 'Join the original digital chef as she makes her debut on Nintendo 3DS with Cooking Mama 4: Kitchen Magic! From new recipes and ways to play to fresh kitchen activities and dish combinations, the iconic kitchen cutie has some tricks up her sleeve that will magically transform kitchen newbies into master culinary artists! Slice, dice, knead, toss and flip your way through more than 200 unique Touch Screen mini-games as you cook in brand new ways with the Nintendo 3DS gyroscope: crack eggs, flip pans, balance plates and much more. Earn bronze, silver and gold medals while mixing up over 60 recipes that range from side dishes to full meals. Organize, decorate and clean your kitchen while watching surprising 3D events unfold as you prepare each meal.' FROM games WHERE igdb_id = 11359 ON CONFLICT (game_id, language_code) DO NOTHING;
