INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cowboys & Aliens', 'Cowboys & Aliens is a 2D action game for mobile phones based on the graphic novel of the same name. As they escort a stagecoach to Silver City, cowboys Zeke and Verity are attacked by Apache Indians while passing through their country. While fighting his way through the Apache camp Zeke witnesses the abduction of some Apache warriors by a UFO. Soon after this, the place is swarming with aliens and Zeke has to find out what is going on.' FROM games WHERE igdb_id = 344313 ON CONFLICT (game_id, language_code) DO NOTHING;
