INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LEGO Ninjago: The Four Paths', 'LEGO Ninjago: The Four Paths is a free Flash-based web game released in 2011 via Cartoon Network. It features four elemental mini-games—Fire Dash, Rocky Road, Flash Dance, and Slippery Slope. Players use the mouse to dodge hazards or jump between platforms, collect coins for points, and occasionally utilize a sheep character for bonuses. The goal is high-score survival in each path rather than progression-based completion.' FROM games WHERE igdb_id = 340034 ON CONFLICT (game_id, language_code) DO NOTHING;
