INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Memories of Replica', 'Memories of Replica is a metroidvania Yume Nikki fangame. It is a sequel to Houchou Shoujo Gensoukyoku, although it is different in both art style and gameplay. The game borrows characters and dream worlds from the original Yume Nikki while giving them actions and positions different to their original counterparts. You play as Poniko who wields scythe as her main weapon.' FROM games WHERE igdb_id = 225348 ON CONFLICT (game_id, language_code) DO NOTHING;
