INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deca Sports Extreme', 'DECA SPORTS, the hit sports compilation series that has over 4 million units sold through worldwide, is coming to the Nintendo 3DS with 10 complete 3D sporting events in DECA SPORTS EXTREME! Kick, shoot, and bounce your way to the top across all of the included events: Soccer, Tennis, Basketball, Ice Hockey, Bowling, Snowball Fight, Sumo Wrestling, Snowmobile Racing, Blowguns, and Trampoline! This all-new handheld version includes several features never seen before in a DECA SPORTS game, like power-ups & un-lockable equipment! Of course, as always, it still features multiplayer and customizable teams. With 10 sports entirely in 3D, DECA SPORTS EXTREME will take sports to a whole new dimension!' FROM games WHERE igdb_id = 6755 ON CONFLICT (game_id, language_code) DO NOTHING;
