INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Harry Potter and the Deathly Hallows: Part 2 - The Mobile Game', 'Live the most thrilling and magical adventure in Harry Potter and the Deathly Hallows - Part 2, the final and ultimate mobile game of the saga. Embody one of the three iconic characters of the saga and engage in the final battle against Lord Voldemort. Experience an astounding battle mode that includes the use of magic and an auto-lock system and confront enemies and bosses from the novel. Gain XP points to increase your level up to 20 and learn new skills, including impressive magic spells!' FROM games WHERE igdb_id = 266199 ON CONFLICT (game_id, language_code) DO NOTHING;
