INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cake Mania: To the Max!', 'Flashback to the neon-soaked 80''s and help a teenage Jill Evans find her true calling in Cake Mania: To the Max!, the sixth chapter in the popular time management series Cake Mania! Help Jill juggle the waves of demanding customers that line the Evans Bakery counters as she prepares for the biggest night in her young life! With all-new equipment upgrades, updated shop mechanics, and interior improvements designed to increase performance, you''ll have Jill on the path to becoming a world-class baker in no time. Play through 100 action-packed levels in Cake Mania: To the Max!' FROM games WHERE igdb_id = 15048 ON CONFLICT (game_id, language_code) DO NOTHING;
