INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Sims 3: Pets', 'Bring excitement and surprise into your Sims'' lives with pets in The Sims 3: Pets, an expansion pack for The Sims 3! Create the perfect (or imperfect) pets for your Sims, from fierce guard dogs to destructive kittens to trusty horses and more as you determine not only how your Sims'' pets look but their personality traits as well. With a variety of new activities and social interactions, take direct control of your Sims'' pets and explore new ways to mess with their lives. Give your Sims a new member of their household and discover all-new ways to play with life!' FROM games WHERE igdb_id = 228496 ON CONFLICT (game_id, language_code) DO NOTHING;
