INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Amanda Rose: The Game of Time', 'Amanda''s father departs for Arizona after taking a strange call from a friend requesting his presence. The next morning, Amanda receives a package from her father indicating that no matter what she hears, he is still alive. Odd she thinks, but soon enough an officer calls her, confirming her father''s message. Now, as Amanda investigates his disappearance, she is about to stumble into an adventure of unimaginable significance.' FROM games WHERE igdb_id = 52399 ON CONFLICT (game_id, language_code) DO NOTHING;
