INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bangai-O HD: Missile Fury', 'Bangai-O HD: Missile Fury is an innovative and insanely addicting arcade shooter combined with puzzle elements that features a sensory overload of thousands of missiles and more than 100 levels! Bangai-O HD: Missile Fury allows players to unleash their creativity with the Level Editor Tool, which allows them to design their own levels and share them with friends online via Xbox LIVE Arcade for the Xbox 360 video game and entertainment system from Microsoft! Bangai-O HD: Missile Fury is based on the cult-classic games Bangai-O and Bangai-O Sprits developed by TREASURE, the renowned Japanese videogame developer. This game provides players with strategic and tactical elements, is a must-have for shooter and puzzle game lovers, and fans will have a blast blowing up bosses and lighting up the screen for the first time in high-definition!' FROM games WHERE igdb_id = 91845 ON CONFLICT (game_id, language_code) DO NOTHING;
