INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'I''m Scared of Girls', 'I’m Scared of Girls, a small RPG Maker 2003 story-driven adventure game developed and published in the rpgmaker.net community by Moga (also known by the username CARRIONBLUE). It tells the story of Lamb, a young cross-dresser who finds himself in a purgatory-like dungeon. There, he must cut the ties to his former life in order to be reborn.' FROM games WHERE igdb_id = 139697 ON CONFLICT (game_id, language_code) DO NOTHING;
