INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gakuen Hetalia Portable', 'Join your favorite personifications of international powers in their madcap adventures in the Hetalia universe (but now you control their fates!). Our heroes have gathered in the prestigious "Sekai W Gakuen", where you play as the girl representation of Seychelles. You must deal with the advances and hijinks of the iconic representations of Italy, Germany, Japan, America, England, France, Russia, and China in a fun academy setting that takes you about town as well as navigating through the academy in sprite-based form.' FROM games WHERE igdb_id = 59419 ON CONFLICT (game_id, language_code) DO NOTHING;
