INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Malgwa Naui Iyagi, Alicia', 'Malgwa Naui Iyagi, Alicia was a 3D online racing game released in South Korea, where players race each other in magical worlds across various race types and tracks, riding a wide range of horses. It was first unveiled by its South Korean developers, Ntreev Soft, under the codename Project Alice in 2007.
