INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bunny Flags 2', 'Subtle mix of shooting and tower defense game, help a rabbit armed to the teeth to protect his flags by repelling successive waves of enemies that will try to take them. By earning experience, you will unlock new abilities as well as various towers to position on the field to secure a larger area. Bunny Flags 2 offers a fast-paced action, many unlockable upgrades and a talent tree, and well-designed missions that make this game very exciting.' FROM games WHERE igdb_id = 387870 ON CONFLICT (game_id, language_code) DO NOTHING;
