INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SingStar: Back to the 80s', 'SingStar: Back to the 80s is a karaoke games with pop songs from the 80s. There are no gameplay changes: player(s) sing into a microphone and the game gives points based on the performance. The only basis of assessment is if the correct note is hit with the correct timeing; the sung words or octave does not play into the result. The game allows access to the SingStore, an online shop for downloading additional songs.' FROM games WHERE igdb_id = 15195 ON CONFLICT (game_id, language_code) DO NOTHING;
