INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('coin-drop', 58196, '2011-04-19', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3glu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc9ehh.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Coin Drop', 'Coin Drop is a game that shares some similarities to pachinko or Peggle. The player is presented with a vertical playfield that consists of pins and other kinds of obstacles. The player drops coins from the top of the screen by tapping the screen. These will then bounce around until they reach one of five buckets at the bottom. Each level has a number of bad pennies and to move on to the next, the player has to hit all of them. The game is played with the touchscreen and the player simply taps where he wants the coins to drop. Up to five coins can be dropped at once. By hitting all buckets the player gets a coin frenzy. This means that five bonus coins automatically gets dropped. Each level has a number of pins that the player gets points for hitting. They then change color and when all pins have changed colour, the points awarded goes up. Some levels have girl coins that have to be rescued. This is often done by destroying Breakout-like bricks so that the coins can fall down to the bottom.' FROM games WHERE igdb_id = 58196 ON CONFLICT (game_id, language_code) DO NOTHING;
