INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Early Bird', 'The Early Bird gets the worm... or at least it can, with your help! Control your bird with simple and intuitive gesture controls to flutter through beautiful landscapes and get past obstacles. Complete 96 amazing levels and earn achievements along the way. Can you top the OpenFeint leaderboard--and, not incidentally, get that Early Bird its morning meal?' FROM games WHERE igdb_id = 368229 ON CONFLICT (game_id, language_code) DO NOTHING;
