INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Trepang', 'Trepang is the story of Wopley the Sea Cucumber, out on an adventure to escape the endless cave. Sadly sea cucumbers aren''t that smart, so Wopley doesn''t realize the cave is endless. In order to "complete" his quest, Wopley must bypass countless evil Starfish, Squids, and Jellyfish blocking his path. But if he can''t escape them, how can he defeat them? BY EJECTING HIS OWN ORGANS OF COURSE! Sea Cucumbers actually do that.' FROM games WHERE igdb_id = 350757 ON CONFLICT (game_id, language_code) DO NOTHING;
