INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('spongebob-squigglepants', 5184, '2011-04-10', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2cyi.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SpongeBob SquigglePants', 'In SpongeBob’s most crazy, creative adventure yet, be prepared to laugh your SquigglePants off as you tilt, flick, tap and draw through more than 100 Nanogames set in six zany worlds. SpongeBob SquigglePants puts you in the driver’s seat for a dizzying series of lightening-speed Nanogames, giving you mere seconds to finish one before moving right on to the next. Within this rapid-fire succession of challenges, SpongeBob SquigglePants exposes players to never-before-seen SpongeBob art styles from the Nickelodeon vault. SpongeBob SquigglePants also lets players digitally draw, paint, color and choose from dozens of SpongeBob-themed stamps, using the uDraw to create a masterpiece worthy of a place in Patchy’s own collection of SpongeBob art, or their own refrigerator, thanks to the uDraw’s exclusive ability to export art to the Wii’s SD card slot. The entire game is hosted by SpongeBob’s biggest fan, Patchy the Pirate, in a never-before-seen live action experience for an added level of under-the-sea silliness.' FROM games WHERE igdb_id = 5184 ON CONFLICT (game_id, language_code) DO NOTHING;
