INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shin Kamai-tachi no Yoru: 11nin-me no Suspect', 'A murder mystery sound novel developed by Chunsoft and the fourth entry in the Kamaitachi no Yoru series. This title attempted to reboot the franchise by returning to a setting similar to the first game, with a group of people trapped in a cabin during a snowstorm, while also introducing new elements such as a real-time polygonal presentation, voice acting and investigative gameplay mechanics, all firsts for the franchise.' FROM games WHERE igdb_id = 43051 ON CONFLICT (game_id, language_code) DO NOTHING;
