INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Evangelion Shin Gekijouban: 3nd Impact', 'Evangelion New Theatrical Edition: 3nd Impact (with "3nd" being pronounced as "sound", it is pun on Third Impact) is a rhythm-action video game for the PlayStation Portable console. It is an adaptation of the anime Neon Genesis Evangelion`s Rebuild of Evangelion movie series, namely 1.0 and 2.0, and was designed by Grasshopper Manufacture.' FROM games WHERE igdb_id = 56810 ON CONFLICT (game_id, language_code) DO NOTHING;
