INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'DreamWoods 2', 'DreamWoods 2 is a puzzle game where you guide a little girl through grid-based levels filled with different blocks. Match blocks to clear obstacles, use bombs to blast your way through, and outsmart a mischievous witch to reach the exit door. Between levels, collect points to decorate your magical garden and progress along a winding path toward the witch’s castle.' FROM games WHERE igdb_id = 361164 ON CONFLICT (game_id, language_code) DO NOTHING;
