INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jewels of the Ages', 'Two full games in one - Jewels of Olympus and Jewels of Ancient Pharaoh''s! You''ve conquered many puzzles before but now you must summon your greatest skills as you take on a series of epic challenges! In your quest to gather a collection of priceless ancient artifacts, countless adventures lie ahead of you. Travel with Odysseus, help conquer the city of Troy, participate in the Olympics, end the Pharaoh''s ancient Curse, and more!' FROM games WHERE igdb_id = 130308 ON CONFLICT (game_id, language_code) DO NOTHING;
