INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Oyadori no Ko', 'It’s widely known among Devil followers. Once upon a time, there was a girl possessed by the Demon. Although the Demon was expelled from her body after that, its words left. "There have to be 9 people offering to the Devil every year on the full moon night. If anyone survives 3 days after being offered to the Devil, the Devil will be back to this world. The Devil will grant this world happiness and freedom.' FROM games WHERE igdb_id = 150552 ON CONFLICT (game_id, language_code) DO NOTHING;
