INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Theatre of War 3: Korea', 'Replay the events of the first hot war of the Cold War era, the Korean War, also known as the Forgotten War. Players will be involved in two campaigns, both set in the 1950''s: the North Korean (June 25 – August 20) and the American (September 15 – October 8).
