INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '100 Classic Games', 'Featuring a wide variety of board, puzzle, logic, dice, card and table-top games, 100 Classic Games is the definitive collection of much loved classics. Whether players want to bluff their way through a hand in Texas Hold''Em, check mate an opponent in chess, win big on the slot machines or number crunch through a Sudoku puzzle, they will be spoilt for choice. Other notable titles in the 100 Classic Games compilation include Air Hockey, Match-3, Freecell, Klondike, Mahjongg, Spot The Difference and Tennis, just to name a few.' FROM games WHERE igdb_id = 97232 ON CONFLICT (game_id, language_code) DO NOTHING;
