INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Uncharted 3: Drake''s Deception - Explorer Edition', 'Exclusive to Europe, Australia and New Zealand is the Uncharted 3: Drake''s Deception - Explorer Edition. It includes the Nathan Drake Statue, belt buckle, and ring/necklace from the North American Collector''s Edition. Instead of including the "Steelbook" case packaging from the Collector''s Edition, the Explorer Edition includes the Special Edition and its DLC, as well as all the pre-order bonuses. The "Traveling Chest" is replaced by the larger "Uncharted Wooden Travel Case", which has space for 19 PlayStation 3 games. A 3D lenticular image is also included.
