INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World Soccer Winning Eleven Arcade Championship 2012', 'World Soccer Winning Eleven Arcade Championship 2012 is a dedicated coin-operated football simulation developed and released by Konami on December 19, 2011 in Japan. Engineered specifically for the arcade environment with unique Konami PC Based hardware and network features absent from home console versions. The cabinet is a substantial industrial unit distinguished by a vertical 32-inch high-definition LCD monitor overlaid with a "Touch Panel System." This touchscreen interface allows players to execute real-time management decisions without pausing the match; you can perform substitutions, alter formations, or issue tactical instructions instantly while the action continues on the pitch. The machine also uniquely integrates front-facing PlayStation 3 and USB controller ports, permitting competitive players to bypass the standard arcade joystick and buttons by plugging in their own gamepads to maintain muscle memory from home practice.' FROM games WHERE igdb_id = 220994 ON CONFLICT (game_id, language_code) DO NOTHING;
