INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Billy''s Boot Camp: Wii de Enjoy Diet!', 'Billy''s Boot Camp: Wii de Enjoy Diet! (ビリーズブートキャンプ Wiiでエンジョイダイエット!) is a fitness game based on the military fitness method advocated by Billy Wayne Blanks in the United States. Levels and popular track inclusions allow players to experience the game''s completely different but equally interesting fun! The game gives players a more efficient fitness slimming effect, displaying the current calorie consumption after each practice. Players can also collect various slimming actions in the form of "action cards".' FROM games WHERE igdb_id = 136884 ON CONFLICT (game_id, language_code) DO NOTHING;
