INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Team Fortress 2 Arcade', 'Team Fortress Arcade is a game created by Eric Ruth, who had previously made side-scrolling versions of Halo and Left 4 Dead. It is a side-scrolling game in which the player, or players, take control of any of the 9 BLU classes from Team Fortress 2 and progress through 9 levels, each of which has one of the RED classes as a level boss – as well as a secret tenth boss which ties into the Portal franchise. The game supports up to 4 players at any one time.' FROM games WHERE igdb_id = 93638 ON CONFLICT (game_id, language_code) DO NOTHING;
