INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Slumberfish!: Catching Z''s', 'In Slumberfish: Catching Z''s, your objective is to get the red beach ball to its goal by clicking the sea life around it. Orange and green fish can knock the ball back and forth, starfish throw the ball in different directions, ocean currents will carry the ball from one place to another, and eels and pufferfish can bounce it while granting access to new areas! Collect golden Z''s while you navigate levels, as they can be used to purchase shortcuts and items!' FROM games WHERE igdb_id = 288677 ON CONFLICT (game_id, language_code) DO NOTHING;
