INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Weiss Schwarz Portable: 2nd Turn', 'Weiss Schwarz Portable 2nd Turn is an expansion for Weiss Schwarz Portable that allows you to fight against some of the series characters. Each character''s voice is used as the announcer. It uses the save data from the main Weiss Schwarz Portable games and has a challenge mode. Once you beat any character you can choose her for a single battle.' FROM games WHERE igdb_id = 269508 ON CONFLICT (game_id, language_code) DO NOTHING;
