INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Allez Raconte', 'Perhaps you have tried to tell a beautiful story of princes and princesses to your offspring to help him find the arms of Morpheus. And maybe you wiped out a ruthless "you tell badly" or "it''s still the same story". Allez Raconte proposes to take over by giving a playful side to the stories via mini-games for the little ones.' FROM games WHERE igdb_id = 269548 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 269548 AND p.igdb_id = 20 ON CONFLICT DO NOTHING;
INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('deluxe-free-cell-solitaire', 86899, '2011-08-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/iqhunkuc4wfpausungd9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/fuiwvdskkbrkpfvtdbcb.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deluxe Free Cell Solitaire', 'Free Cell solitaire is one of the all time solitaire fan favorites. Unlike many solitaire games, free cell solitaire is a fun and challenging game that requires more strategy than luck. Deluxe Free Cell plays standard 52 card free cell solitaire. It''s simple to play, but also includes lots of options and features that are sure to please the most serious free cell player. Deluxe Free Cell will take advantage of larger displays for clear and easy to read cards. It supports high definition resolutions up to a game window size of 1920x1080. It also includes a convenient toolbar, appearance options, numbered games, statistics tracking, records best times, secondary mouse support, undo, redo, and much more.' FROM games WHERE igdb_id = 86899 ON CONFLICT (game_id, language_code) DO NOTHING;
