INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dora & Kai-Lan''s Pet Shelter', 'Two heroic Nickelodeon stars are teaming up like never before to find new homes for pets in need. Its Dora and Kai-lan''s Pet Shelter! With help from Kai-lan''s grandfather YeYe and Dora''s cousin Diego, Dora & Kai-Lan invite kids to help them at their Pet Shelter where they care for puppies, kittens, bunnies, and birds. Dora and Kai-lan''s Pet Shelter helps pets get clean, fed, healthy, and happy so they can be adopted! Once pets are adopted, they aren''t gone for good because Dora and Kai-lan need your help to run a daycare for returning animals too!' FROM games WHERE igdb_id = 97372 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 97372 AND p.igdb_id = 20 ON CONFLICT DO NOTHING;
