INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('haunted-domains', 54078, '2011-09-05', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co40jq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar16vs.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Haunted Domains', 'Get ready for Halloween with this fang-tastic game for iPhone! As the manager of a haunted hotel, you''re in charge of tending to the needs of an assortment of comical creatures of the night. With 50 levels of side-splitting time management fun, Haunted Domains will have you howling with delight! Guide Sheila Sullivan as she checks in guests, serves dinner, cleans rooms and performs special tasks in an effort to keep her ghoulish guests happy. Purchase magical upgrades that make Sheila work faster, decorate your hotels to suit the macabre tastes of your guests and enlist the help of Igor when things get out of hand. Finally, take your earnings and restore a rundown garden to its former glory!' FROM games WHERE igdb_id = 54078 ON CONFLICT (game_id, language_code) DO NOTHING;
