INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Top Sailor', 'Top Sailor is a highly realistic sailing and motorboat simulator. Take Top Sailor with you and learn basics of sailing! See how wind force affects the sail and test your skills against AI opponents in a yacht race. Learn how to trim the sails to make the most use of wind energy. Discover when there is a risk of capsizing. Practise sailing downwind and upwind, tacking and gybing. Improve navigation skills, sail race strategy and tactics.' FROM games WHERE igdb_id = 175143 ON CONFLICT (game_id, language_code) DO NOTHING;
