INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Youda Mystery: The Stanwick Legacy', 'Uncover your grandfather''s secret in Youda Mystery: The Stanwick Legacy, an hidden object puzzle adventure! After inheriting Stanwick Manor, Emma searches the house and discovers that there is a secret to reveal. Finding proof that the house isn’t as abandoned as she was led to believe, Emma must now solve clever puzzles and make her way into locked rooms to discover the truth behind the mansion in Youda Mystery: The Stanwick Legacy!' FROM games WHERE igdb_id = 104403 ON CONFLICT (game_id, language_code) DO NOTHING;
