INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Forza Motorsport 4: Limited Collector''s Edition', 'Forza Motorsport 4 is a racing video game, and the fourth in the Forza Motorsport series. Like Sony''s Gran Turismo franchise, Forza games are racing simulations; heavy emphasis is placed on making the cars drive and look as realistic as possible. Races are conducted on closed circuit tracks. 500 cars are featured in the core game experience, ranging from road cars to race cars.' FROM games WHERE igdb_id = 41600 ON CONFLICT (game_id, language_code) DO NOTHING;
