INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blowup!!', 'Time to gear up!!! Blowup!! is an iOS puzzle game where you try to connect eight or more of the same colored blocks to blow them up. Developed by Cravemob, the application works on the iPhone, iPod Touch and the iPad. Try to connect as many of the same colored blocks to transform them into robots which in turn will blow up. The music in this game changes depending on how far you can last. One song can have a variety of mixes which adds an addictive quality to the game just to hear them all.' FROM games WHERE igdb_id = 233246 ON CONFLICT (game_id, language_code) DO NOTHING;
