INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lee-Lee''s Quest', 'Lee-Lee has fallen in love with Lu-Lu… unfortunately, being with her is not an easy thing, considering the fact that there’s a bad guy somewhere who also wants to be with Lu-Lu. She left, and you are after her, still hoping that she will be with you forever. Help Lee-Lee or he will be unhappy for eternity!' FROM games WHERE igdb_id = 54611 ON CONFLICT (game_id, language_code) DO NOTHING;
