INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Solitaire Kingdom Supreme', 'Solitaire Kingdom is a fresh and fun version of your favorite Solitaire game. Play the Solitaire you know and love, but now you get to win special cards that will give you fantastic new powers. Add these cards to your deck and become the Solitaire master you know you are. Features include: Quick play which lets you play fast with just one click per card, an Award system that rewards you for big plays, and infinite Daily Challenges that keeps the fun going, and going, and going.' FROM games WHERE igdb_id = 175323 ON CONFLICT (game_id, language_code) DO NOTHING;
