INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Egress - The Test of STS-417', 'Egress is a short form sci-fi adventure game set in the outer reaches of space. The story begins when you, the commander of a two man recon team, are sent hurtling into space during maintenance on an interplanetary probe. After a sudden attack from an black alien substance, you awake on a mysterious planet. Where are you? How did you get there? And why is your partner screaming for help down the intercom…' FROM games WHERE igdb_id = 168393 ON CONFLICT (game_id, language_code) DO NOTHING;
