INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Word Up', 'Challenge your brain with Word Up, a collection of classic word games that will keep your gray matter busy for hours! Includes fast paced favorites like WordBlast, Pickletter, and updated versions of Hangman and Wordfinder. Experience the very best "pick-up-and-play" word games with "challenge mode" and over 100,000 words to take your word puzzle experience to a different level!' FROM games WHERE igdb_id = 206484 ON CONFLICT (game_id, language_code) DO NOTHING;
