INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'I Must Run', 'You have been convicted of a crime you didn''t mean to commit. Your sentence was harsh despite the circumstances, and now you rot in jail. But those affected by your actions are not satisfied. Now, they are threatening to kill the one you love to exact revenge. And if you do not escape and reach the courthouse in 24 hours, she''ll be gone. There are no other options. You must run.' FROM games WHERE igdb_id = 42824 ON CONFLICT (game_id, language_code) DO NOTHING;
