INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Homesteader', 'Homesteader is an engaging tile-matching game that challenges players to construct a thriving homestead by gathering essential resources. In this game, players strategically match three or more adjacent tiles on an 8x8 grid. What sets Homesteader apart from typical matching games is its unique feature of tile movement in all eight directions, including diagonal swaps. This allows for even more strategic gameplay and opens up exciting possibilities for players to maximize their progress.' FROM games WHERE igdb_id = 62660 ON CONFLICT (game_id, language_code) DO NOTHING;
