INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'We Dare', 'We Dare is an adult-oriented party video game by Ubisoft, for the Wii and PlayStation 3 gaming systems. It is marketed as a "sexy, quirky, party game" and involves kissing, striptease and spanking. However reviewers in countries where the game is available, such as Canada have noted that the game is in fact a relatively tame party game compilation with only very mild sexual connotations.' FROM games WHERE igdb_id = 22946 ON CONFLICT (game_id, language_code) DO NOTHING;
