INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'I Heart Geeks!', 'I Heart Geeks! is the ultimate puzzle experience, challenging you to create sophisticated and humorous contraptions using dozens of objects and the laws of real-world physics to solve over 100 brain teasers. Produced in cooperation with Marc Ecko Entertainment, the game features a tongue-in-cheek story and hip art style where the brainy Geek overcomes the brawny (and bullying) Jocks, winning the heart of the beautiful Cheerleader.' FROM games WHERE igdb_id = 84456 ON CONFLICT (game_id, language_code) DO NOTHING;
