INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Need for Speed: Shift 2 Unleashed - Limited Edition', 'The critically acclaimed shift franchise returns to the track with shift 2 unleashed. The most immersive racing experience to date brings the true driver''s experience to life with all the intensity and exhilaration of being behind the wheel and competing in the driver''s battle. From the all-new helmet cam to night racing to frighteningly real physics and crashes, shift 2 unleashed delivers all the violence and excitement of race day in a groundbreaking authentic racing experience.' FROM games WHERE igdb_id = 142546 ON CONFLICT (game_id, language_code) DO NOTHING;
