INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mysterious Castle', 'A minimal touch interface controls a party of adventurers in a turn-based adventure set in a procedurally generated open world filled with monsters and treasure. Control 1-4 characters as they explore and engage in tactical turn based combat with enemy parties of monsters in a huge open world. Use combat techniques, spells, bows, wands, staffs, potions, sneak-attacks, and more to dispatch monsters and make your way to the bottom of the network of dungeons that dot the forest.' FROM games WHERE igdb_id = 205008 ON CONFLICT (game_id, language_code) DO NOTHING;
