INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mini-U: Mosaic', 'The game has a number of small and big cards, or “boards” with patterns based on a grid, and a bank of pins which are used to complete the board. The patterns are made of colored circles, and the object is to place identically-colored “pins” from the bank on those circles by touching the pin of the correct color and then touching the grid location where they want it. It requires very simple motor skills, yet engages the mind and the brain in several ways.' FROM games WHERE igdb_id = 175408 ON CONFLICT (game_id, language_code) DO NOTHING;
