INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Face Racers: Photo Finish', '"Developed by Renegade Kid, Face Kart: Photo Finish lets players tilt and turn the Nintendo 3DS to steer their photo customized speedsters through 20 unique race tracks, as they drift around corners, soar over chasms and speed past the competition. Players use the Nintendo 3DS camera to snap their own picture and then map it onto their avatar, the landscape or even a turbo boost so they can pick up their very own power-ups as they race. Each avatar offers up to one hundred choices in hair, clothing and eyewear, plus cars can also be customized by tuning and tweaking to create the ultimate personalized racer."' FROM games WHERE igdb_id = 44008 ON CONFLICT (game_id, language_code) DO NOTHING;
