INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Inversion 2 HD', 'Space Inversion is the highly rated arcade Invader style shooter and it''s back with a vengeance! Bigger and better than ever before and now featuring a new Arcade mode with regenerating aliens and power ups to even the odds. New bonus "Meteor Storm" and "Flying Saucer" rounds add yet more thrills and the chance to rack points up for extra lives. There''s also a Classic mode for those wanting a slower paced more traditional game.' FROM games WHERE igdb_id = 174313 ON CONFLICT (game_id, language_code) DO NOTHING;
