INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Family Quiz', 'Family Quiz on Wii is an exciting quiz game with board game elements and minigames, packed with several thousand questions on a wide variety of topics! Quiz questions on a wide variety of topics such as history, politics, physics, chemistry, mathematics, general knowledge, geography, biology and sport, some of which are accompanied by picture puzzles and video clips. Three different multiplayer modes and a Survivor mode for solo players are ready to challenge one to four players. The questions are divided into three age categories so that the whole family can join in the fun. Mini-games involving coordination and skill provide a change of pace and add to the overall excitement! A detailed highscore provides hours of gaming fun and motivation to play over and over again!' FROM games WHERE igdb_id = 268129 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 268129 AND p.igdb_id = 5 ON CONFLICT DO NOTHING;
