INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dance Dance Revolution II', 'Dance Dance Revolution II, later released in Europe as Dance Dance Revolution Hottest Party 5, is a music video game in the Dance Dance Revolution series by Konami. It was released on October 11, 2011[1] for the Nintendo Wii in North America and on November 24, 2011 for Europe. Dance Dance Revolution II is the direct sequel to Dance Dance Revolution for the Wii. This game shares songs with the arcade version of Dance Dance Revolution X3 vs 2ndMix. It features characters from the arcade versions of Dance Dance Revolution.' FROM games WHERE igdb_id = 50684 ON CONFLICT (game_id, language_code) DO NOTHING;
