INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Airwave: I Fought the Law and the Law One', 'Elodie Major has been running a little indie radio station called Airwave Radio with her friend Zak for 5 years now, and they''ve manage to win a strong following amongst the people of the small town of Wave. Recently, however, they''ve found themselves under pressure from mainstream record labels to play their music, and have resisted quite forcefully, but they haven''t seen an end to this attempted interference just yet... This is the first part in the ~airwave~ series of games.' FROM games WHERE igdb_id = 169988 ON CONFLICT (game_id, language_code) DO NOTHING;
