INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mega Man RPG: Prototype', 'Mega Man RPG Prototype is a browser-based fangame where you square off against hordes of increasingly challenging robot masters in turn-based battles, paying tribute to the battle systems of retro role-playing games released in the late 80s and early 90s. Prototype merges the combat and collection mechanics of the Pokémon series with the beloved characters and special weapons of the classic Mega Man series to create something familiar yet unexplored. The story unfolds in the original series timeline and features elements from across those games, but Battle Network fans may also recognize a familiar face or two. With three distinct campaigns, more than a hundred playable characters, and an ever-expanding array of unique abilities, there''s a wealth of discovery awaiting in The Prototype.' FROM games WHERE igdb_id = 288040 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 288040 AND ge.slug = 'role-playing-rpg' ON CONFLICT DO NOTHING;
