INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Escapology', 'Escapology is a simple yet challenging puzzle solving game with a unique atmosphere, challenging levels and beautiful retina graphics. Your task in each level is to move one or more wooden balls into their designated positions. Controls are really simple, just swipe in any direction and the whole board will move. As you progress further in the game, those new puzzles will need more and more of your brain power to solve.' FROM games WHERE igdb_id = 174582 ON CONFLICT (game_id, language_code) DO NOTHING;
