INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Omochabako no Kuni no Alice: Wonderful Wonder World', 'Omochabako no Kuni no Alice: Wonderful Wonder World is a fandisc that was released in 2011. The game was originally going to be on PC, but was instead released on the PSP. Toybox has two stories - one is a parody of Quinrose''s first game, Wizard and the Master, and the other is an original story set in Wonderland. There are 26 different story arcs.' FROM games WHERE igdb_id = 218782 ON CONFLICT (game_id, language_code) DO NOTHING;
