INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Flying Hamster', 'Take control of Newton, the flying hamster in this action-frenzy horizontal shooter. You will fly across six unique environments, from the sunflower fields to the big Japanese city or the crazy ancient Egypt. Eight freaky weapons are scattered among the levels, and you''ll need them all to take on the more than 35 different enemies (sneaky penguins, anti-air cows, exploding foxes, ninja squirrels, toaster-robots...) as well as the six dreadful and unpredictable bosses.' FROM games WHERE igdb_id = 42825 ON CONFLICT (game_id, language_code) DO NOTHING;
