INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hollywood Files: Deadly Intrigues', 'Help Zoey, a private detective, find out who killed a famous star in Hollywood Files: Deadly Intrigues, a fun Hidden Object game! After a man is murdered, it''s up to Zoey to get to the bottom of the case and bring the killer to justice! Explore locations throughout Hollywood and use your keen detective skills to close another case before the trail turns cold in Hollywood Files: Deadly Intrigues!' FROM games WHERE igdb_id = 269631 ON CONFLICT (game_id, language_code) DO NOTHING;
