INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'FlyMe2theMoon', 'Fly me to the moon! As the heiress of the Kaslana family, the 16-year-old witch Kiana has always dreamed of finding the Eclipse and restoring honor to her family name. With 60 engaging levels, you will experience superb graphics, unique gameplay, and a captivating storyline that will make you fall in love with Kiana. Download now and fly to the moon with Kiana!' FROM games WHERE igdb_id = 214827 ON CONFLICT (game_id, language_code) DO NOTHING;
