INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ace Combat: Northern Wings', 'Ace Combat: Northern Wings brings Ace Combat to the retro top-down shooter genre. Players take control of Grendel 1, a pilot serving the secretive Kingdom of Nordennavic. The country officially maintains neutrality throughout the events of past Ace Combat games, but sends Grendel 1 to covertly influence their outcomes. Developed on Java, Northern Wings is the second Ace Combat game playable on mobile devices after Ace Combat Xi: Skies of Incursion.' FROM games WHERE igdb_id = 175783 ON CONFLICT (game_id, language_code) DO NOTHING;
