INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Utility Vehicle Simulator', 'Utility Vehicle Simulator (German: "Sonderfahrzeug-Simulator 2012") is a simulation that lets you complete communal or private assignments. Repairing street lights, cleaning sewers, grooming trees or cordoning off construction sites. 15 missions and a lot of vehicles are included and can be controlled by you. Maintenance as well as financial management are also your responsibilities.' FROM games WHERE igdb_id = 276059 ON CONFLICT (game_id, language_code) DO NOTHING;
