INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bloody Checkers', 'Enter the medieval world of Knotted Hand Hall, and take on 20 dead NPC’s who will try and stop you at all costs. Enjoy 30 hours of leveling, exploring, and hiding as you take everything you have learned online. Gorgeous graphics and 3D gameplay almost go unnoticed as the action overtakes you and you become immersed in volleys of spells, arrow barrages, and cannon attacks from your opponents.' FROM games WHERE igdb_id = 272068 ON CONFLICT (game_id, language_code) DO NOTHING;
