INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Phone Story', 'Phone Story is a game for smartphone devices that attempts to provoke a critical reflection on its own technological platform. Under the shiny surface of our electronic gadgets, behind its polished interface, hides the product of a troubling supply chain that stretches across the globe. Phone Story represents this process with four educational games that make the player symbolically complicit in coltan extraction in Congo, outsourced labor in China, e-waste in Pakistan and gadget consumerism in the West.' FROM games WHERE igdb_id = 62455 ON CONFLICT (game_id, language_code) DO NOTHING;
