INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ever17', 'Ever17 is a remake of "Ever17: The Out of Infinity", developed in collaboration between 5pb. and CyberFront. This remake, among other things, features a significantly rewritten script, re-done voice acting, a remixed soundtrack, and animated 3D models to replace the static character sprites of the original.' FROM games WHERE igdb_id = 221220 ON CONFLICT (game_id, language_code) DO NOTHING;
