INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '3 Days: Amulet Secret', 'Join Anna in a series of fabulous and thrilling adventures in 3 Days: Amulet Secret. Unravel the mysteries of Stonehenge and plunge yourself into the curious blend of Egyptian symbolism and Tibetan spirit in this challenging Hidden Object game. Intriguing storyline and enigmatic characters create the atmosphere of a real detective story. But hurry up, because you have only three days to catch the criminals and find the parts of the amulet. You are the only one who can save the world.' FROM games WHERE igdb_id = 25464 ON CONFLICT (game_id, language_code) DO NOTHING;
