INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rurouni Kenshin: Meiji Kenkaku Romantan - Saisen', 'Displeased with his path of bloodshed, Kenshin picks up the lifestyle of a wandering samurai who fights only in the name of peace and has vowed to stop killing. Shortly afterward, he rescues Kaoru Kamiya, the young instructor of a kendo school, and goes on to form bonds with numerous other allies in his dangerous quest for atonement.' FROM games WHERE igdb_id = 42838 ON CONFLICT (game_id, language_code) DO NOTHING;
