INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Trader HD', 'Even if traders don''t have rules, the markets do. The aim of the game is to have the most money at the end. Each player begins with the same amount. Stocks worth between 2 and 6 million dollars in 5 different colors are shared randomly between 5 stock markets.' FROM games WHERE igdb_id = 175085 ON CONFLICT (game_id, language_code) DO NOTHING;
