INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tamagotchi iD L 15th Anniversary Version', 'The Tamagotchi iD L 15th Anniversary Version is the limited edition fifteenth anniversary Tamagotchi iD L. It was released on November 23, 15 years after Tamagotchi first debuted. It comes in two colors, Royal Pink and Royal Purple, and has 11 new characters added. The baby, child, and teen characters return from previous entries in the Tamagotchi series. The new adult characters were pulled from the top rankings of a popularity poll featuring vintage, plus era, and anime-exclusive characters. There are also new locations and Henshin Jo transformations.' FROM games WHERE igdb_id = 230021 ON CONFLICT (game_id, language_code) DO NOTHING;
