INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Assault Fire', 'Assault Fire is a free-to-play, first-person shooter MMO that features a combination of traditional MMOFPS games with a few sci-fi elements. Set in a futuristic war-torn world, players will assume the role of an elite soldier of the GSDU (Global Security Defense Unit). The game offers an exciting gaming experience with its solid character customization, lobby-based format, and loadout. It also has diversified game modes and maps, and the futuristic integration from cyborg to mech.' FROM games WHERE igdb_id = 137583 ON CONFLICT (game_id, language_code) DO NOTHING;
