INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Insectonator: Zombie Mode', 'The Insectonator series continues with Insectonator: Zombie Mode, where instead of killing bugs, you kill zombies that are only the size of bugs. There is a new mode called ''Don''t Touch My Gem,'' where you defend your gem from being taken by zombies within the time limit, along with a new variety of weapons such as the sword and basketball, along with many other old weapons.
