INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'DMBX: Mountain Biking', 'Go fast, show incredible tricks and earn coins - that’s DMBX: Mountain Biking in short words! DMBX: Mountain Biking is a fresh mix of downhill racing and trick challenges featuring 10 amazing & unique bike trails with 30 time-, coin- and score challenges. Earn coins to access faster bikes and clear the score challenges to unlock new characters with more power. Each character has his own style and a unique, special trick in his/her repertoire!' FROM games WHERE igdb_id = 174213 ON CONFLICT (game_id, language_code) DO NOTHING;
