INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chuck E. Cheese''s Super Collection', 'The Chuck E. Cheese''s Super Collection offers over 25 fun-filled mini-games that the whole family can enjoy! Included are Chuck E. Cheese''s Party Games & Sports Games collections. Challenge your friends and family in the ultimate party game showdown as you and your friends play with the King of Cool himself and his international group of friends! Make pizzas, race around the track in trucks, win cool prizes and so much more! It''s the only place where a kid can be a kid! Join Chuck E. Cheese and his friends Helen, Pasqually, Jasper and Mr. Munch as you swing, shoot, steer and putt your way to victory! Play a variety of fun filled sports as you compete to become an all-star athlete. Do well to earn experience and medals to make it to the Professional League!' FROM games WHERE igdb_id = 51044 ON CONFLICT (game_id, language_code) DO NOTHING;
