INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dariusburst: Another Chronicle EX', 'Dariusburst: Another Chronicle, or Darius Burst: Another Chronicle, is a shoot em up video game released in 2010 for Arcades, and a remix of Dariusburst. The game was largely expanded upon and rereleased in 2011 as Dariusburst: Another Chronicle EX. It was later included as a extra mode in Dariusburst Chronicle Saviours.' FROM games WHERE igdb_id = 138014 ON CONFLICT (game_id, language_code) DO NOTHING;
