INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dungeon Siege III: Limited Edition', 'Torn asunder, the delicate balance of power between the kingdom of Ehb''s powerful factions has fallen apart. As one of the few remaining members of the disgraced protectors of the land, the 10th Legion, it is up to you to rebuild the once great Legion and stop Ehb from falling into darkness. Joined by a group of unique companions, you will travel through the striking land of Ehb defeating all manner of villains and beasts through a combination of heroic abilities, screen shaking magic and pure cunning.' FROM games WHERE igdb_id = 44551 ON CONFLICT (game_id, language_code) DO NOTHING;
