INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cute Things Dying Violently', 'Cute Things Dying Violently is all about saving a bunch of hapless Critters. Launch them around to get them safely out of each level. Dodge lethal spikes, buzzsaws, fire, and hateful robots. And, if a few dozen (or hundred) of them get turned into charred, smoking husks in your attempt to save them... there''s the old saying about omelettes and breaking eggs. Broken, bloody eggs.' FROM games WHERE igdb_id = 12394 ON CONFLICT (game_id, language_code) DO NOTHING;
