INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dark Souls: Collector''s Edition', 'Dark Souls: Collector''s Edition is a special edition of the action role-playing game Dark Souls, developed by FromSoftware and published by Bandai Namco Entertainment. Released in October 2011, this edition includes the full base game and a range of exclusive bonuses. It comes in a special collector''s box featuring unique artwork and includes a physical art book with concept art, character designs, and illustrations from the game. The edition also provides access to behind-the-scenes videos, including developer interviews and making-of content. Additionally, it features the official game soundtrack, composed by Motoi Sakuraba, and a mini-strategy guide to assist players in navigating the game''s challenging world' FROM games WHERE igdb_id = 44607 ON CONFLICT (game_id, language_code) DO NOTHING;
