INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('concurrence', 166779, '2011-05-07', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3ryp.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sccxsv.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Concurrence', 'Concurrence is a so called cinematic platform game. Unlike other platform games you will know (like Super Mario Bros. or Sonic the Hedgehog), this game focuses on realistic movements, puzzles and a dense atmosphere. If you have played games like Prince of Persia, Another World, or Flashback, you will know what awaits you. Many of parts of the game will require precise jumping and you might feel a little frustrated at the beginning. But don''t despair, study the movements described in the manual and keep on practicing and you will find that it isn''t so hard after all (you also have unlimited continues).' FROM games WHERE igdb_id = 166779 ON CONFLICT (game_id, language_code) DO NOTHING;
