INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Magnolia Manor', 'The Haunting of Magnolia Manor is a strategy game in which you try to use various abilities to frighten off guests from your old estate. During each level, you are given a planning phase, and then the actual gameplay phase. During the planning phase, you place abilities that you feel will be the most effective; during the actual gameplay, you activate other abilities to get your job done.' FROM games WHERE igdb_id = 140162 ON CONFLICT (game_id, language_code) DO NOTHING;
