INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('naught', 117751, '2011-09-27', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1l0a.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arce6.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Naught', 'Naught is a platform videogame with a unique control where you rotate the environment to change gravity and guide the main character, Naught, through labyrinth levels full of challenges, hidden places and secrets. Featuring varied, dynamic gameplay, Naught explores 40 levels where he must dodge danger and enemies arising from the shadows, discover hidden places, collect seeds of light that will help him access blocked areas, and recover the diamond fragments that possess enormous power. Throughout his adventure, he will be accompanied by the Spirit of the Tree, who will help him find his way through extremely narrow and complex labyrinths. You can also enjoy a time trial challenge on every level. In Naught, you will discover an underground world full of lights and shadows, connected to the exciting story of our character: a soul awakened to face the shadows and protect what he loves the most.' FROM games WHERE igdb_id = 117751 ON CONFLICT (game_id, language_code) DO NOTHING;
