INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spy Kids: All the Time in the World', 'In Spy Kids: All the Time in the World the video game, players will step into the shoes of the newest Spy Kids, Rebecca and Cecil, as they race against the clock in this all out platforming adventure. The Timekeeper is threatening to take over the planet and it’s up to you to stop him from realizing his evil scheme. Utilize the coolest new hi-tech spy gear to take out swarms of enemies and solve puzzles that stand in your way. The clock is ticking, so gear up and reinvigorate the Spy Kids division for a new generation!' FROM games WHERE igdb_id = 124058 ON CONFLICT (game_id, language_code) DO NOTHING;
