INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kamen Rider: Climax Heroes Fourze', 'Kamen Rider: Climax Heroes Fourze is a Japanese fighting game developed by Eighting and Bandai Namco Entertainment for the PlayStation Portable and Nintendo Wii. Serving as the sequel to Climax Heroes OOO, it is the fourth installment of the Kamen Rider: Climax series and celebrates the 40th anniversary of the franchise. Thus, it features all Heisei-era Riders up until Fourze, as well as a selection of Showa-era Riders as playable characters. A sequel featuring Wizard was released in 2012.' FROM games WHERE igdb_id = 64239 ON CONFLICT (game_id, language_code) DO NOTHING;
