INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tamagotchi iD L', 'Tamagotchi iD L is a Tamagotchi virtual pet, the 3rd verison to have a full-color screen. It is the successor to the Tamagotchi iD, and includes new features and up to 32 new characters. As with the iD, it is based on the concurrently-airing Tamagotchi! Anime. The L stands for many words - Life, Link, Live, Love, Leader and Limited.' FROM games WHERE igdb_id = 230020 ON CONFLICT (game_id, language_code) DO NOTHING;
