INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Artemis Blue', 'In 2040, a mysterious natural disaster causes all planes to stop functioning above 500 feet (150 meters) of the Earth’s surface, resulting in over 20 million deaths. The year is 2060 and it is forbidden to fly above this limit. Pilots call this stretch from 500 feet to outer space ‘Artemis’s hymen’. Now a group of people operate a transport agency from the abandoned building that was to be the New Third Tokyo International Airport (nicknamed Edowanzu). They wish to fly higher than what is permitted by aviation laws.
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 321543 AND p.igdb_id = 6 ON CONFLICT DO NOTHING;
