INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sakaagari Hurricane Portable', 'Takumi transfers to a new high school where Yukari, his old friend, goes. He visits the school for a preview and meets a girl there. On the next day, when he goes to school, there is that girl in his class. He is appointed class president and ordered to take care of an opinion box. One day, a piece of paper is put in the box and it stimulates his curiosity. From that day, his boring school life gradually changes...' FROM games WHERE igdb_id = 140114 ON CONFLICT (game_id, language_code) DO NOTHING;
